    background-color: rgba(136, 57, 239, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #6c6f85 !important;
  }
  :root .dcg-desmos-svg-logo g {
    fill: #4c4f69;
  }
  :root .dcg-expression-top-bar {
    border-right-color: #ccd0da !important;
    border-bottom-color: #ccd0da !important;
  }
  :root .user-info,
  :root .dcg-saved-graphs-tile-or-row,
  :root .dcg-graph-list__header-row {
