  :root .dcg-product-filter__button {
    border-color: #4c4f69 !important;
  }
  :root .dcg-btn-white-outline.dcg-hovered,
  :root .dcg-end-test-button.dcg-hovered {
    box-shadow: 0 0 0 1px #4c4f69 !important;
  }
  :root .dcg-arrow::after,
  :root .dcg-add-inference-wizard__header {
    border-bottom-color: #4c4f69 !important;
  }
  :root .dcg-expressionitem.dcg-selected {
    border-color: #8839ef !important;
    --dcg-item-border-color: #8839ef !important;
  }
  :root .dcg-expressionitem:not(.dcg-selected) {
    border-top-color: #ccd0da !important;
  }
  :root .dcg-popover-title,
  :root .dcg-dropdown-popover__title,
  :root .dcg-help-menu-title {
    color: #8839ef !important;
    background-color: transparent !important;
    border-bottom-color: #8839ef !important;
  }
  :root .dcg-toggle-track {
    background: #6c6f85 !important;
  }
  :root .dcg-toggle-switch,
  :root .dcg-or-separator {
    background: #4c4f69 !important;
  }
  :root .dcg-toggled .dcg-toggle-switch {
    background: #8c8fa1 !important;
  }
  :root .dcg-keypad-btn.dcg-btn-light-on-gray,
  :root .dcg-keypad-btn.dcg-btn-light-gray,
  :root .dcg-ctrl-toggle-cover {
    background: #e6e9ef !important;
    border-color: #ccd0da !important;
  }
  :root .dcg-keypad-btn.dcg-btn-dark-on-gray {
    background: #dce0e8 !important;
    border-color: #ccd0da !important;
  }
  @layer {
    :root .dcg-btn-short-blue,
    :root .dcg-btn-blue,
    :root .dcg-copy-button {
      background: #8839ef !important;
      border-color: transparent !important;
      color: #eff1f5 !important;
    }
    :root .dcg-btn-short-blue *,
    :root .dcg-btn-blue *,
